sketch.css:
.hc{position:relative;box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:8px;padding:12px 14px;background:var(--window);color:var(--text);font:13px/1.4 "Segoe UI",system-ui,sans-serif;overflow:hidden}
.hc *{box-sizing:border-box}
.top{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
.label{color:var(--muted);font-size:12.5px;font-weight:500}
.valuerow{display:flex;align-items:baseline;gap:8px}
.value{font-size:28px;font-weight:700;letter-spacing:-.02em;line-height:1.2}
.sub{color:var(--muted);font-size:12px}
.flag{font-size:12px;font-weight:600;padding:2px 9px;border-radius:10px;white-space:nowrap}
.flag.ok{color:var(--positive);background:color-mix(in srgb,var(--positive) 14%,transparent)}
.flag.bad{color:var(--negative);background:color-mix(in srgb,var(--negative) 14%,transparent)}
.legend{display:flex;flex-wrap:wrap;gap:4px 14px;color:var(--muted);font-size:11.5px}
.legend i{display:inline-block;width:10px;height:8px;border-radius:2px;margin-right:5px;vertical-align:baseline}
.chart{flex:1;min-height:90px;display:flex;gap:6px}
.axis{position:relative;width:30px;margin-bottom:20px;margin-top:16px;color:var(--muted);font-size:10.5px}
.axis span{position:absolute;right:0;transform:translateY(50%)}
.plot{position:relative;flex:1;margin-top:16px}
.grid{position:absolute;left:0;right:0;top:0;bottom:20px;border-bottom:1px solid var(--border)}
.grid b{position:absolute;left:0;right:0;border-top:1px dashed var(--border);opacity:.6}
.band{position:absolute;left:0;right:0;border-top:1px dashed var(--accent);border-bottom:1px dashed var(--accent);background:color-mix(in srgb,var(--accent) 10%,transparent)}
.cols{position:absolute;left:0;right:0;top:0;bottom:0;display:flex;gap:4px}
.col{flex:1;min-width:0;display:flex;flex-direction:column;cursor:pointer;border-radius:5px}
.col:hover{background:var(--hover)}
.col.selected{background:var(--hover);box-shadow:inset 0 -3px 0 var(--accent)}
.stack{position:relative;flex:1}
.bar{position:absolute;left:18%;right:18%;bottom:0;display:flex;flex-direction:column-reverse;border-radius:3px 3px 0 0;overflow:hidden}
.seg{background:var(--c)}
.seg.phy{opacity:.45}
.bar.in{--c:var(--accent)}
.bar.below{--c:var(--negative)}
.bar.above{--c:var(--warning)}
.pct{position:absolute;left:0;right:0;text-align:center;font-size:11px;font-weight:600;font-variant-numeric:tabular-nums;padding-bottom:1px}
.pct.below{color:var(--negative)}
.mon{height:20px;text-align:center;color:var(--muted);font-size:11.5px;padding-top:3px;white-space:nowrap;overflow:hidden}
.col.selected .mon{color:var(--accent);font-weight:600}
.tip{position:absolute;display:none;pointer-events:none;z-index:5;background:var(--text);color:var(--window);border-radius:6px;padding:6px 9px;font-size:11.5px;line-height:1.5;white-space:nowrap;box-shadow:0 2px 8px rgba(20,20,50,.25)}
.tip b{font-weight:600}
.empty{color:var(--muted);font-size:12px;padding:30px 0;text-align:center;width:100%}

