function render(root, props, fire) {
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const num = v => { v = +v; return isFinite(v) ? v : 0; };
  const fmt = v => Math.round(v).toLocaleString();
  const unit = props.unit || '';
  const pmin = num(props.policyMin), pmax = num(props.policyMax);
  const host = root.querySelector('.hc');

  const rows = (props.months || []).filter(m => m && m.month).map(m => {
    const exp = Math.max(0, num(m.exposure)), fut = Math.max(0, num(m.futures)), phy = Math.max(0, num(m.physical));
    const hedged = fut + phy, pct = exp ? hedged / exp * 100 : 0;
    const status = pct < pmin ? 'below' : pct > pmax ? 'above' : 'in';
    return { month: String(m.month), exp, fut, phy, hedged, pct, status };
  });

  root.querySelector('.label').textContent = props.title || 'Hedge coverage';
  const near = rows.slice(0, 12);
  const te = near.reduce((a, r) => a + r.exp, 0), th = near.reduce((a, r) => a + r.hedged, 0);
  root.querySelector('.value').textContent = (te ? Math.round(th / te * 100) : 0) + '%';
  const out = rows.filter(r => r.status !== 'in').length;
  const flag = root.querySelector('.flag');
  flag.className = 'flag ' + (out ? 'bad' : 'ok');
  flag.textContent = out ? out + (out === 1 ? ' month' : ' months') + ' out of policy' : 'All months in policy';

  root.querySelector('.legend').innerHTML =
    '<span><i style="background:var(--accent)"></i>In policy</span>' +
    '<span><i style="background:var(--negative)"></i>Under-hedged</span>' +
    '<span><i style="background:#e0a100"></i>Over-hedged</span>' +
    '<span><i style="background:var(--muted);opacity:.9"></i>Futures</span>' +
    '<span><i style="background:var(--muted);opacity:.45"></i>Fixed-price physical</span>' +
    '<span><i style="background:color-mix(in srgb,var(--accent) 18%,transparent);border:1px dashed var(--accent)"></i>Policy ' + pmin + '–' + pmax + '%</span>';

  const top = Math.max(100, Math.ceil(Math.max.apply(null, rows.map(r => r.pct).concat([0])) / 10) * 10);
  const y = v => (v / top * 100);
  const plot = root.querySelector('.plot');
  const band = root.querySelector('.band');
  band.style.display = pmax > pmin ? '' : 'none';
  band.style.bottom = 'calc(20px + (100% - 20px) * ' + (y(pmin) / 100) + ')';
  band.style.height = 'calc((100% - 20px) * ' + (y(Math.max(pmax, pmin) - pmin) / 100) + ')';

  const ticks = [0, 25, 50, 75, 100].filter(t => t <= top);
  root.querySelector('.axis').innerHTML = ticks.map(t => '<span style="bottom:calc(' + (y(t) / 100) + ' * 100%)">' + t + '%</span>').join('');
  root.querySelector('.grid').innerHTML = ticks.filter(t => t > 0).map(t => '<b style="bottom:' + y(t) + '%"></b>').join('');

  const cols = root.querySelector('.cols');
  if (!rows.length) { cols.innerHTML = '<div class="empty">No hedge data</div>'; return; }
  cols.innerHTML = rows.map(r => {
    const h = y(r.pct), fh = r.hedged ? r.fut / r.hedged * 100 : 0;
    return '<div class="col' + (r.month === props.selected ? ' selected' : '') + '" data-m="' + esc(r.month) + '">' +
      '<div class="stack"><div class="bar ' + r.status + '" style="height:' + h + '%">' +
      '<div class="seg fut" style="height:' + fh + '%"></div><div class="seg phy" style="flex:1"></div></div>' +
      '<div class="pct ' + (r.status === 'below' ? 'below' : '') + '" style="bottom:' + h + '%">' + Math.round(r.pct) + '%</div></div>' +
      '<div class="mon">' + esc(r.month) + '</div></div>';
  }).join('');

  const tip = root.querySelector('.tip');
  cols.querySelectorAll('.col').forEach((el, i) => {
    const r = rows[i];
    el.onclick = () => fire('monthSelected', { month: r.month });
    el.onmouseenter = () => {
      tip.innerHTML = '<b>' + esc(r.month) + '</b> · ' + r.pct.toFixed(0) + '% hedged<br>Hedged ' + fmt(r.hedged) + ' of ' + fmt(r.exp) + ' ' + esc(unit) +
        '<br>Futures ' + fmt(r.fut) + ' · Physical ' + fmt(r.phy) + '<br>Policy ' + pmin + '–' + pmax + '%';
      tip.style.display = 'block';
    };
    el.onmousemove = ev => {
      const b = host.getBoundingClientRect();
      let x = ev.clientX - b.left + 12, yy = ev.clientY - b.top + 12;
      if (x + tip.offsetWidth > b.width - 4) x = ev.clientX - b.left - tip.offsetWidth - 12;
      if (yy + tip.offsetHeight > b.height - 4) yy = ev.clientY - b.top - tip.offsetHeight - 12;
      tip.style.left = Math.max(4, x) + 'px'; tip.style.top = Math.max(4, yy) + 'px';
    };
    el.onmouseleave = () => { tip.style.display = 'none'; };
  });
}
